(function() {
    'use strict';
    tinymce.PluginManager.add('wptoc', function(editor, url) {
        editor.addButton('wptoc', {
            title: 'Table of Contents',
            tooltip: 'Table of Contents [toc]',
            icon: 'toc-custom-icon',
            onPostRender: function() {
                var btn = this;
                var iconEl = btn.$el.find('.mce-ico');
                if (iconEl && iconEl.length) {
                    iconEl.html('<svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" focusable="false" style="display:block;margin:auto;"><path d="M5 5c.6 0 1 .4 1 1s-.4 1-1 1a1 1 0 1 1 0-2Zm3 0h11c.6 0 1 .4 1 1s-.4 1-1 1H8a1 1 0 1 1 0-2Zm-3 8c.6 0 1 .4 1 1s-.4 1-1 1a1 1 0 0 1 0-2Zm3 0h11c.6 0 1 .4 1 1s-.4 1-1 1H8a1 1 0 0 1 0-2Zm0-4c.6 0 1 .4 1 1s-.4 1-1 1a1 1 0 1 1 0-2Zm3 0h8c.6 0 1 .4 1 1s-.4 1-1 1h-8a1 1 0 0 1 0-2Zm-3 8c.6 0 1 .4 1 1s-.4 1-1 1a1 1 0 0 1 0-2Zm3 0h8c.6 0 1 .4 1 1s-.4 1-1 1h-8a1 1 0 0 1 0-2Z" fill-rule="evenodd"></path></svg>');
                }
            },
            onclick: function() {
                editor.insertContent('[toc]');
            }
        });

        // Backward compatibility alias for button name
        editor.addButton('toc_mce_button', {
            title: 'Table of Contents',
            tooltip: 'Table of Contents [toc]',
            icon: 'toc-custom-icon',
            onPostRender: function() {
                var btn = this;
                var iconEl = btn.$el.find('.mce-ico');
                if (iconEl && iconEl.length) {
                    iconEl.html('<svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" focusable="false" style="display:block;margin:auto;"><path d="M5 5c.6 0 1 .4 1 1s-.4 1-1 1a1 1 0 1 1 0-2Zm3 0h11c.6 0 1 .4 1 1s-.4 1-1 1H8a1 1 0 1 1 0-2Zm-3 8c.6 0 1 .4 1 1s-.4 1-1 1a1 1 0 0 1 0-2Zm3 0h11c.6 0 1 .4 1 1s-.4 1-1 1H8a1 1 0 0 1 0-2Zm0-4c.6 0 1 .4 1 1s-.4 1-1 1a1 1 0 1 1 0-2Zm3 0h8c.6 0 1 .4 1 1s-.4 1-1 1h-8a1 1 0 0 1 0-2Zm-3 8c.6 0 1 .4 1 1s-.4 1-1 1a1 1 0 0 1 0-2Zm3 0h8c.6 0 1 .4 1 1s-.4 1-1 1h-8a1 1 0 0 1 0-2Z" fill-rule="evenodd"></path></svg>');
                }
            },
            onclick: function() {
                editor.insertContent('[toc]');
            }
        });
    });
})();
